, {"id": "91910bcf-1e16-41ff-b360-814c00275987", "type": "concept", "title": "Point of view"}, {"id": "39a323a2-11ce-4b13-a889-c2fc91fff85b", "type": "concept", "title": "Continuity and discontinuity"}], "description": "Why it matters: A shared vocabulary lets students make precise claims about style, affect, narrative, and meaning."}]}, {"id": "556139c8-c037-4692-84a2-8ada03384cbe", "type": "topic", "title": "Film Historiography, Archives, and Canon Formation", "description": "Study how film histories are written, preserved, contested, and organized into canons and counter-canons.", "children": [{"id": "ea12d81f-b226-4a9f-8a9c-864bed150e64", "type": "subtopic", "title": "Historiography", "children": [{"id": "9635813e-9a11-44c9-8d40-73bc3c1df958", "type": "concept", "title": "Periodization"}, {"id": "ff3ebd25-48d0-4247-b516-9d5ea1c6bfe2", "type": "concept", "title": "Primary sources"}, {"id": "2ce4f55f-c1b9-41a0-bc18-fe29aeceaedf", "type": "concept", "title": "Industrial history"}, {"id": "5fa3a081-10e4-4ed3-bd15-beb648e45e15", "type": "concept", "title": "Reception history"}], "description": "Why it matters: Film history is constructed through methods, archives, institutions, and critical priorities."}, {"id": "22d7d369-2178-497f-9c16-422397196c3e", "type": "subtopic", "title": "Archives and preservation", "children": [{"id": "fa300bd3-5666-4b33-b259-38870c4f18d6", "type": "concept", "title": "Film archives"}, {"id": "070bc237-47f1-45a1-adc4-e24b51aac7ae", "type": "concept", "title": "Restoration"}, {"id": "c32c7b81-0c28-4bec-aacd-b635bd75ce25", "type": "concept", "title": "Lost films"}, {"id": "02b59b63-e4ec-4d41-b0ab-f5ba0f1994da", "type": "concept", "title": "Material formats"}], "description": "Why it matters: Students learn how survival, restoration, and access shape what can be studied."}, {"id": "346cd491-37fb-4030-a136-976ef1cdf3a7", "type": "subtopic", "title": "Canon and counter-canon", "children": [{"id": "c4d439b3-2429-46e6-bd64-80b25d1f378e", "type": "concept", "title": "Auteur canon"}, {"id": "2d00b907-f0cb-4fe9-a5b3-fcb3309bc0b6", "type": "concept", "title": "National cinemas"}, {"id": "80bf6c92-be3c-4ec8-a259-025cd11d1e8b", "type": "concept", "title": "World cinema"}, {"id": "df316b6f-a8e8-4990-98b4-96e3493f3153", "type": "concept", "title": "Marginalized film histories"}], "description": "Why it matters: Canons reveal value judgments and exclusions, making them objects of critique."}]}, {"id": "9ecec249-19a4-4528-a589-d9e061c0b88c", "type": "topic", "title": "Realism, Formalism, Montage, and Classical Film Theory", "description": "Introduce foundational debates about cinema's relation to reality, artifice, movement, editing, and modernity.", "children": [{"id": "96ae29a2-500c-4e41-962a-aff1e00820a4", "type": "subtopic", "title": "Realism", "children": [{"id": "b377efdc-b116-43c4-9eff-6c6ad4f21f90", "type": "concept", "title": "Bazin"}, {"id": "1e1dc66f-aa78-45a3-8691-a6ebafdbd15a", "type": "concept", "title": "Kracauer"}, {"id": "df9d24ae-0b2d-41e5-a079-d85f6b30d5dd", "type": "concept", "title": "Long takes"}, {"id": "9b1d4a5d-cf9f-45b1-b95a-12b9bc4f5cc2", "type": "concept", "title": "Deep focus"}], "description": "Why it matters: Realist theory asks what cinema reveals about the world and how indexicality matters."}, {"id": "0078b16c-7ba3-405c-882d-55e12ce9e290", "type": "subtopic", "title": "Formalism", "children": [{"id": "2e985c91-a22d-46df-9166-983d16162cb1", "type": "concept", "title": "Eisenstein"}, {"id": "eaf9fb89-a749-4ca4-a24e-be348eea5c74", "type": "concept", "title": "Pudovkin"}, {"id": "3e43afd2-2b9f-4946-8362-c8fd1a5623b2", "type": "concept", "title": "Formal pattern"}, {"id": "4870c63e-e204-4718-a2d6-03aa9992014f", "type": "concept", "title": "Cinematic specificity"}], "description": "Why it matters: Formalist theory treats cinema as an art of construction, rhythm, defamiliarization, and design."}, {"id": "ba463c0f-0adc-4102-95eb-da6ad72c7179", "type": "subtopic", "title": "Montage theory", "children": [{"id": "0465b578-9c77-4435-9ec3-e25822214b2a", "type": "concept", "title": "Metric montage"}, {"id": "5c4e879e-42e8-4b24-8459-a7ecd95aa4f9", "type": "concept", "title": "Intellectual montage"}, {"id": "c234f073-5dc7-4fdd-b9d5-879330c7b702", "type": "concept", "title": "Kuleshov effect"}, {"id": "2a28e91d-8548-41ca-b3f0-425b389df3ff", "type": "concept", "title": "Dialectical editing"}], "description": "Why it matters: Montage shows how editing can produce ideas, affect, conflict, and political force."}]}, {"id": "0799f6a8-227b-468f-91fb-8486c2f11b13", "type": "topic", "title": "Mise-en-Scene, Cinematography, Editing, and Sound as Theory", "description": "Treat style not as decoration but as an argument about meaning, perception, power, and experience.", "children": [{"id": "916a279c-b538-46b3-ad58-435d36996671", "type": "subtopic", "title": "Mise-en-scene", "children": [{"id": "167ba116-5762-49d5-80a9-1f33adcaed77", "type": "concept", "title": "Blocking"}, {"id": "8b8195e4-ba11-4047-9765-97c7ec308533", "type": "concept", "title": "Lighting"}, {"id": "a4a1294a-d4bc-4926-b12f-2dd7a638f689", "type": "concept", "title": "Production design"}, {"id": "d3d3f03b-be3e-41cb-ace4-860335daa586", "type": "concept", "title": "Performance style"}], "description": "Why it matters: Staging, performance, setting, costume, and lighting are theoretical claims about worlds and bodies."}, {"id": "35d4ce64-bcce-414c-becf-a0983177f98e", "type": "subtopic", "title": "Image and camera", "children": [{"id": "b8910574-a9d1-4978-bc5c-0e939414fcdb", "type": "concept", "title": "Lens choice"}, {"id": "09bde01a-4b4f-4599-ad90-0f9bd265f084", "type": "concept", "title": "Camera angle"}, {"id": "26db6f13-3d02-4759-8112-956780c28a56", "type": "concept", "title": "Color design"}, {"id": "97c8a30e-cb6f-4d3b-861f-5fd24fc805be", "type": "concept", "title": "Aspect ratio"}], "description": "Why it matters: Cinematography shapes spectatorship through perspective, scale, movement, texture, and color."}, {"id": "0daa358c-ff94-4bbe-88c9-7b10df7f7531", "type": "subtopic", "title": "Editing and sound", "children": [{"id": "90f9987c-20e5-4e9c-88f9-73bda1681ec6", "type": "concept", "title": "Continuity editing"}, {"id": "e138ad4e-1e7c-45fd-9bff-ab442c8ee396", "type": "concept", "title": "Discontinuity"}, {"id": "4a49693d-6cd4-4026-b88d-7f8d668990d1", "type": "concept", "title": "Sound bridge"}, {"id": "c81d4c01-eb54-4013-a978-ade6d5dec58c", "type": "concept", "title": "Voice-over"}], "description": "Why it matters: Editing and sound organize time, space, attention, rhythm, and interiority."}]}, {"id": "bd779dd9-5bbe-4dc8-b598-4de31c152836", "type": "topic", "title": "Narrative Theory, Authorship, and Auteur Criticism", "description": "Analyze story, narration, authorship, collaboration, and the critical uses and limits of auteur theory.", "children": [{"id": "ec97c81b-ee0b-498f-8ddc-b823aa2be592", "type": "subtopic", "title": "Narration and story", "children": [{"id": "ca94551d-0cd0-49ab-825e-828829489ee1", "type": "concept", "title": "Fabula and syuzhet"}, {"id": "e0a7247b-1517-4812-8e84-ec5320dcd641", "type": "concept", "title": "Narrator"}, {"id": "d55a0284-aa2b-4e12-a36c-7b7ee39dfa77", "type": "concept", "title": "Focalization"}, {"id": "a1145559-4e8d-4f09-ad9f-3ae7d14f5ade", "type": "concept", "title": "Unreliable narration"}], "description": "Why it matters: Narrative theory separates what happens from how films organize knowledge, time, and perspective."}, {"id": "f647ef16-71e8-4648-b544-341de9144412", "type": "subtopic", "title": "Auteur theory", "children": [{"id": "d1c533d5-463f-4c0b-8984-833cce2e0f30", "type": "concept", "title": "Director signature"}, {"id": "d70fbcd1-da1b-4921-b349-1b3b955e352d", "type": "concept", "title": "Collaborative authorship"}, {"id": "e0fdba4d-1a3d-4c96-a314-13c047bc99f0", "type": "concept", "title": "Studio authorship"}, {"id": "eac3272f-d372-453c-8a33-c404cd1c7c94", "type": "concept", "title": "Auteurism critique"}], "description": "Why it matters: Auteur criticism asks how authorship appears across collaboration, style, theme, and institution."}, {"id": "e9e9fe96-2b82-4b77-b3c9-03818630dc37", "type": "subtopic", "title": "Adaptation and intertextuality", "children": [{"id": "1a95e9a9-2f9a-4fa9-a352-89fcc8a6fa8b", "type": "concept", "title": "Adaptation theory"}, {"id": "f721f7f3-a214-474f-b5a5-29f6e754b709", "type": "concept", "title": "Remake"}, {"id": "3653b75a-38de-48d4-bc96-367ff66cb52c", "type": "concept", "title": "Intertextual reference"}, {"id": "84d649df-18a8-4224-808e-76fc4b8d105f", "type": "concept", "title": "Franchise authorship"}], "description": "Why it matters: Films speak with other texts, genres, and cultural memory."}]}, {"id": "7eacd053-9773-4308-bddc-46da499a2b38", "type": "topic", "title": "Genre Theory, Popular Cinema, and Cultural Meaning", "description": "Understand genres as historical systems of convention, repetition, difference, industry practice, and social meaning.", "children": [{"id": "bc670653-4b51-4efd-8b0c-2b0bcad2ce77", "type": "subtopic", "title": "Genre systems", "children": [{"id": "a0c3d026-6882-4437-bf9c-ff7a03f98746", "type": "concept", "title": "Conventions"}, {"id": "cb111793-b343-4541-aa2e-3f936c609790", "type": "concept", "title": "Iconography"}, {"id": "c17b613f-b202-4bd1-a123-33b812fb73b9", "type": "concept", "title": "Narrative patterns"}, {"id": "e1599fad-4ad4-4d1c-99bf-88b8726c9be9", "type": "concept", "title": "Audience expectations"}], "description": "Why it matters: Genres are not fixed categories but evolving contracts among filmmakers, industries, texts, and audiences."}, {"id": "9812e25c-2a94-4467-8c1f-2f34b4232c47", "type": "subtopic", "title": "Genre and ideology", "children": [{"id": "7bc35220-da02-4a22-8e52-2f75e83b5664", "type": "concept", "title": "Western"}, {"id": "5e22b05d-22f9-4a67-9cbe-fa46dea0cb90", "type": "concept", "title": "Film noir"}, {"id": "62bb96e8-8500-41f1-9613-947693b053ee", "type": "concept", "title": "Horror"}, {"id": "c4dd84bd-5b17-424f-aa82-07bf40caa4a8", "type": "concept", "title": "Melodrama"}], "description": "Why it matters: Genre films encode social fantasies, conflicts, fears, and desires."}, {"id": "84fd374d-3bac-4688-9c95-3935f79fcb5a", "type": "subtopic", "title": "Genre change", "children": [{"id": "27c704cc-e077-44eb-9edc-e88b9cd28cef", "type": "concept", "title": "Genre cycles"}, {"id": "9ddb4405-159b-49fa-8509-67ea0466d2d4", "type": "concept", "title": "Hybridity"}, {"id": "47ea83a7-cf2e-41d5-9a0d-ab699d632a38", "type": "concept", "title": "Revisionist genre"}, {"id": "4d6df70d-fa51-4697-b630-372bab851cd8", "type": "concept", "title": "Transnational genre"}], "description": "Why it matters: Genres mutate through cycles, hybridity, parody, revision, and global circulation."}]}, {"id": "61487ade-79bb-463a-a7e9-7fc4ff3a1795", "type": "topic", "title": "Psychoanalysis, Apparatus Theory, and Spectatorship", "description": "Examine theories of desire, identification, cinematic apparatus, subject formation, and viewing positions.", "children": [{"id": "5512b559-7b6e-4f3e-91cf-2af1a7d7395b", "type": "subtopic", "title": "Psychoanalytic concepts", "children": [{"id": "e5f633c8-1173-48ba-a38e-b0b8f2004767", "type": "concept", "title": "Freud"}, {"id": "86f12052-d040-49b6-bda6-226bc924a44b", "type": "concept", "title": "Lacan"}, {"id": "4bcc257e-6b30-4a17-8922-13ebf55498ab", "type": "concept", "title": "The unconscious"}, {"id": "31a2d2b5-be93-41f9-a58b-74e0b14ea8b1", "type": "concept", "title": "Desire"}], "description": "Why it matters: Psychoanalysis shaped film theory's accounts of desire, fantasy, identification, and lack."}, {"id": "f291c176-0167-43c3-b08f-ad758262a494", "type": "subtopic", "title": "Apparatus theory", "children": [{"id": "a73d04fa-bcc7-49e6-b06e-48842942734e", "type": "concept", "title": "Suture"}, {"id": "315bc368-b7e7-4e22-bb74-99561610f1dc", "type": "concept", "title": "Identification"}, {"id": "a3e3713f-7442-4c34-bdda-1c207ad6eb17"